/// The queues of one device, with the depth of each counted from the stored tasks.
///
/// Both quantum-task queues are reported, as AWS reports a device's queues whether or
/// not anything is waiting in them. The hybrid-jobs queue is reported at zero because
/// `CreateJob` is still a stub, so this emulator holds no hybrid jobs at all.
fn queue_info(
    state: &crate::state::ComAmazonawsBraketBraketState,
    device_arn: &str,
) -> Vec<DeviceQueueInfo> {
    let queued = state.queued_tasks_on(device_arn);
    let priority_depth = queued
        .iter()
        .filter(|t| t.queue_priority() == crate::state::PRIORITY_PRIORITY)
        .count();
    let normal_depth = queued.len() - priority_depth;
    vec![
        DeviceQueueInfo {
            queue: crate::state::QUEUE_QUANTUM_TASKS.to_string(),
            queue_size: normal_depth.to_string(),
            queue_priority: Some(crate::state::PRIORITY_NORMAL.to_string()),
        },
        DeviceQueueInfo {
            queue: crate::state::QUEUE_QUANTUM_TASKS.to_string(),
            queue_size: priority_depth.to_string(),
            queue_priority: Some(crate::state::PRIORITY_PRIORITY.to_string()),
        },
        DeviceQueueInfo {
            queue: crate::state::QUEUE_JOBS.to_string(),
            queue_size: "0".to_string(),
            queue_priority: None,
        },
    ]
}

